"""AZ-104 Domain 5: Monitor and maintain Azure resources (5.1 Azure Monitor, 5.2 Backup and Site Recovery)."""
from builder import animation, lesson, q

E = "az-104"
ML = "https://learn.microsoft.com/azure/"
T = "frontend/src/simulations/groups/monitor.test.ts"
_n = {"i": 0}


def qa(obj, diff, typ, stem, opts, correct, expl, doc, code=None):
    _n["i"] += 1
    L = "abcdefgh"
    mode = "ordering" if typ == "ordering" else "multiple" if len(correct) > 1 else "single"
    args = [f"az104-q-mon-{_n['i']}", E, obj, diff, typ, mode, stem]
    if code:
        args.append(code)
    q(*args, [(L[i], o[0], o[1]) for i, o in enumerate(opts)], list(correct), expl, [doc])


def cfg(portal, cli, ps, prereq=("An Azure subscription with VMs to monitor or protect",), perms=("Monitoring Contributor (alerts, diagnostic settings) or Backup Contributor (vaults, policies)",), limits=("See Azure Monitor / Azure Backup service limits",)):
    return dict(prerequisites=list(prereq), permissions=list(perms), limits=list(limits), portal=portal, cli=cli, powershell=ps)


def lab(objective, steps, expected, validation, failures, duration=15):
    return dict(type="A", objective=objective, duration=duration, steps=steps, expected=expected, validation=validation, failures=failures)


animation("monitor-sim", "Azure Monitor: metrics, log settings, KQL, alerts, Insights and Network Watcher", E, [f"AZ104-5.1.{i}" for i in range(1, 7)], "accurate-model", T,
          "Aggregation over a CPU spike, a working KQL evaluator over a sample Perf table, metric alerts with action groups and alert processing rules, data-source choices, Insights and Connection Monitor.")
animation("backup-dr-sim", "Azure Backup and Site Recovery: vaults, policies, restore, failover and reports", E, [f"AZ104-5.2.{i}" for i in range(1, 8)], "accurate-model", T,
          "Vault choice per data source, policy validation (Standard vs Enhanced), restore options including Cross Region Restore, an Azure-to-Azure DR drill and reporting prerequisites.")

