# ================================================================ 5.1.1 + 5.1.2 metrics and log settings
lesson(
    id="az104-monitor-metrics-logs", exam=E, title="Azure Monitor metrics and log settings", objectives=["AZ104-5.1.1", "AZ104-5.1.2"], minutes=45,
    objective="Interpret metrics in Metrics explorer and configure the right collection (activity log, diagnostic settings, Azure Monitor Agent with data collection rules) and destinations.",
    prereqs=["Basic familiarity with VMs and storage accounts"],
    foundation=["Azure Monitor collects two main kinds of data: metrics (numbers over time, such as CPU %) and logs (records of events with many fields).",
                "Platform metrics are collected automatically for most resources. Logs from inside resources need configuration.",
                "A chart only shows what its aggregation and time grain reveal: a 1-hour average can hide a 3-minute spike."],
    engineer=["Metrics: platform metrics every minute, kept 93 days; Metrics explorer chooses scope, metric, aggregation (Average, Min, Max, Sum, Count), time range and granularity; split or filter by dimensions (for example per disk LUN or per API name). Pin charts to dashboards or workbooks.",
              "Activity log: subscription-level control-plane events (create, delete, role changes, service health), kept 90 days. Export with a diagnostic setting for longer retention or KQL.",
              "Resource logs (data-plane: Key Vault access, storage reads, NSG events) are not collected until you create a diagnostic setting choosing categories and destinations: Log Analytics workspace (query/alert), Storage account (archive), Event Hubs (stream to SIEM), partner solutions. Up to 5 diagnostic settings per resource.",
              "Guest OS data (performance counters, Windows events, Syslog, text logs) needs the Azure Monitor Agent plus a data collection rule (DCR) that says what to collect and where to send it. The legacy Log Analytics agent is retired.",
              "Log Analytics workspace settings: region, access control mode (resource-context or workspace), table plans and retention (interactive retention plus long-term retention up to 12 years), daily cap."],
    anim=("monitor-sim", "Interpret metrics, and Log settings and data sources tabs."),
    diagram=([("res", "Azure resources", 20, 60, "service"), ("vm", "VM guest (AMA + DCR)", 20, 200, "compute"), ("m", "Metrics store (93 days)", 300, 20, "storage"), ("ds", "Diagnostic settings", 300, 120, "security"), ("law", "Log Analytics", 560, 60, "storage"), ("st", "Storage archive", 560, 160, "storage"), ("eh", "Event Hubs → SIEM", 560, 240, "network")],
             [("res", "m", "automatic"), ("res", "ds", "resource logs"), ("ds", "law"), ("ds", "st"), ("ds", "eh"), ("vm", "law", "DCR")]),
    example=("A slow website", ["The 1-hour average CPU chart looks fine, but switching to Maximum at 1-minute granularity reveals 97% spikes every evening during backups.",
                                "To investigate requests, the team adds a diagnostic setting on the App Service sending HTTP logs to Log Analytics."]),
    config=cfg(["Monitor > Metrics: select scope, metric, aggregation; set time range and granularity; Apply splitting.", "Resource > Diagnostic settings > + Add: choose categories and destinations.", "Monitor > Data collection rules > Create: choose VMs (installs AMA), data sources and the workspace.", "Monitor > Activity log: filter and export."],
               "az monitor metrics list --resource $VM_ID --metric \"Percentage CPU\" --aggregation Maximum --interval PT1M\naz monitor log-analytics workspace create -g rg-mon -n law-ops --retention-time 90\naz monitor diagnostic-settings create -n to-law --resource $KV_ID --workspace law-ops --logs '[{\"categoryGroup\":\"allLogs\",\"enabled\":true}]' --metrics '[{\"category\":\"AllMetrics\",\"enabled\":true}]'\naz monitor data-collection rule create -g rg-mon -n dcr-windows --location eastus --rule-file dcr.json\naz monitor activity-log list --offset 1d --query \"[?operationName.value=='Microsoft.Resources/subscriptions/resourceGroups/delete']\"",
               "Get-AzMetric -ResourceId $vmId -MetricName 'Percentage CPU' -AggregationType Maximum -TimeGrain 00:01:00\nNew-AzOperationalInsightsWorkspace -ResourceGroupName rg-mon -Name law-ops -Location eastus -Sku PerGB2018\n$log = New-AzDiagnosticSettingLogSettingsObject -CategoryGroup allLogs -Enabled $true\nNew-AzDiagnosticSetting -Name to-law -ResourceId $kvId -WorkspaceId $lawId -Log $log\nGet-AzActivityLog -StartTime (Get-Date).AddDays(-1)"),
    lab=lab("Find a hidden spike and choose the right collection for each data source.", ["Interpret metrics: run the default (Average, 1 hour).", "Apply 'Maximum at 1 minute'.", "Log settings and data sources: answer every requirement."],
            ["Aggregation and grain change what you see", "Resource logs need diagnostic settings", "Guest data needs AMA + DCR"],
            [("metrics-spike-found", "Revealed the spike with the right aggregation"), ("metrics-spike-hidden", "Saw aggregation hide a spike"), ("mon-data-correct", "Chose the right collection/destination")],
            ["Using a 1-hour average", "Expecting resource logs without a diagnostic setting", "Using the retired Log Analytics agent"]),
    troubleshooting=[("Log Analytics has no Key Vault logs.", "No diagnostic setting.", "Create one with the AuditEvent/allLogs category."), ("Perf table is empty for a VM.", "No Azure Monitor Agent or DCR.", "Associate a DCR (installs the agent)."), ("Can't see who deleted a resource 4 months ago.", "Activity log keeps 90 days.", "Export the activity log to a workspace or storage.")],
    comparisons=[("Amazon CloudWatch", "Metrics, logs and alarms; CloudTrail is the activity log equivalent."), ("Application Insights", "Application performance monitoring (requests, dependencies, traces) built on Azure Monitor.")],
    misconceptions=[("Azure collects all logs automatically.", "Only platform metrics and the activity log; resource and guest logs need configuration."), ("The average shows the worst case.", "Use Maximum for peaks.")],
    decisions=["Send logs to one central workspace per environment unless data residency or access requires more.", "Use Azure Policy to deploy diagnostic settings and DCRs at scale.", "Set retention and table plans to control cost."],
    docs=[("Azure Monitor overview", MON), ("Azure Monitor metrics", METRICS), ("Diagnostic settings", DIAG), ("Azure Monitor Agent", AMA)],
)
qa("AZ104-5.1.1", 2, "scenario", "Users reported slowness for 3 minutes, but the CPU chart (Average, 1-hour granularity) shows 35%. What should you change?", [("Use Maximum aggregation and 1-minute granularity", "Correct."), ("Use Minimum aggregation", "Hides peaks."), ("Increase the time range to 30 days", "Coarser grain."), ("Create a diagnostic setting", "Metrics are already there.")], "a", "Short spikes disappear in long averages.", METRICS)
qa("AZ104-5.1.1", 2, "single", "How long are platform metrics retained in Azure Monitor metrics?", [("93 days", "Correct."), ("7 days", "No."), ("2 years", "No."), ("Forever", "No.")], "a", "Send to Log Analytics for longer analysis.", METRICS)
qa("AZ104-5.1.1", 2, "scenario", "A storage account's Transactions metric must be shown per API (GetBlob, PutBlob). What do you use?", [("Apply splitting by the API name dimension", "Correct."), ("A diagnostic setting", "Not needed for metrics."), ("A different aggregation", "No."), ("KQL only", "Metrics explorer supports dimensions.")], "a", "Split by dimension.", METRICS)
qa("AZ104-5.1.2", 2, "configuration", "You must query Key Vault access events with KQL. What do you configure?", [("A diagnostic setting sending Key Vault logs to a Log Analytics workspace", "Correct."), ("Nothing; they're collected automatically", "Resource logs need a setting."), ("Azure Monitor Agent on Key Vault", "Agents are for machines."), ("An Event Hub only", "Streams, not KQL.")], "a", "Resource logs → diagnostic setting → workspace.", DIAG)
qa("AZ104-5.1.2", 2, "scenario", "You need Windows Security event logs from 40 VMs in a workspace. What do you deploy?", [("Azure Monitor Agent with a data collection rule", "Correct."), ("A diagnostic setting on each VM resource", "Gives platform data, not guest events."), ("Activity log export", "Control plane only."), ("Network Watcher", "No.")], "a", "Guest data needs AMA + DCR.", AMA)
qa("AZ104-5.1.2", 2, "single", "Which diagnostic setting destination is best for streaming logs to a third-party SIEM?", [("Event Hubs", "Correct."), ("Storage account", "Archive."), ("Log Analytics workspace", "Azure-native analysis."), ("Metrics store", "Not a destination.")], "a", "Event Hubs streams to external tools.", DIAG)

# ================================================================ 5.1.3 KQL
lesson(
    id="az104-kql", exam=E, title="Querying logs with KQL", objectives=["AZ104-5.1.3"], minutes=40,
    objective="Write and run Kusto Query Language (KQL) queries in Log Analytics to filter, summarise and visualise monitoring data.",
    prereqs=[("Metrics and log settings", "AZ104-5.1.2", "az104-monitor-metrics-logs")],
    foundation=["Log Analytics stores logs in tables (Perf, Heartbeat, Event, Syslog, AzureActivity, AzureDiagnostics, StorageBlobLogs…).", "A KQL query starts with a table and pipes (|) the rows through operators, like a production line."],
    engineer=["Core operators: where (filter), project (choose columns), extend (add calculated columns), summarize (aggregate with count(), avg(), max(), percentile() by columns or bin(TimeGenerated, 1h)), order by / sort, take / limit, top, join, render (timechart, barchart).",
              "Time: queries use the time range picker or where TimeGenerated > ago(1h). Use bin() to group by time for charts.",
              "Useful queries: Heartbeat | summarize LastSeen = max(TimeGenerated) by Computer | where LastSeen < ago(5m) (missing agents); AzureActivity | where OperationNameValue endswith 'DELETE'; Perf | where CounterName == '% Processor Time' | summarize avg(CounterValue) by bin(TimeGenerated, 5m), Computer | render timechart.",
              "Scope: workspace, or resource context (only that resource's data). Save queries, pin to dashboards or workbooks, and use them in log search alerts."],
    anim=("monitor-sim", "Query logs with KQL tab: queries run over a sample Perf table."),
    diagram=([("t", "Perf table", 20, 120, "storage"), ("w", "| where", 200, 120, "service"), ("s", "| summarize by", 360, 120, "service"), ("o", "| order by", 520, 120, "service"), ("r", "| render timechart", 680, 120, "user")], [("t", "w"), ("w", "s"), ("s", "o"), ("o", "r")]),
    example=("Finding the busiest VMs", ["Perf | where CounterName == \"% Processor Time\" | summarize AvgCPU = avg(CounterValue) by Computer | order by AvgCPU desc | take 5 shows vm-db1 at the top; a timechart by bin(TimeGenerated, 1h) shows it rising all morning."]),
    config=cfg(["Monitor > Logs (or the workspace > Logs): choose scope and time range.", "Write the query in KQL mode, Run, then Chart or Pin to dashboard.", "Save the query to a query pack; create a log search alert from it."],
               "az monitor log-analytics query -w <workspace-guid> --analytics-query \"Perf | where CounterName == '% Processor Time' | summarize avg(CounterValue) by Computer | order by avg_CounterValue desc\" -t P1D",
               "Invoke-AzOperationalInsightsQuery -WorkspaceId <workspace-guid> -Query \"Heartbeat | summarize LastSeen = max(TimeGenerated) by Computer | where LastSeen < ago(5m)\"",
               perms=("Log Analytics Reader on the workspace (or resource-context read on the resources)",)),
    lab=lab("Build queries that filter, summarise and order performance data.", ["Run the default (Heartbeat table) and read the semantic error.", "Apply 'Busiest VMs (avg CPU)'.", "Apply 'CPU samples above 80%'.", "Apply 'Hourly trend for vm-db1'."],
            ["Choose the right table", "summarize … by", "order and take"], [("kql-summarized", "Ran a summarize query"), ("kql-filtered", "Ran a filtered query"), ("kql-error", "Fixed a query error")], ["Wrong table", "Filter that removes all rows"]),
    troubleshooting=[("Query returns no rows.", "Time range too short or filters too strict, or data not collected.", "Widen the range; check the table has data (… | take 10)."), ("Failed to resolve column.", "Column doesn't exist in that table.", "Check the schema pane."), ("Query is slow.", "Scanning large tables without a time filter.", "Filter on TimeGenerated first and project only needed columns.")],
    comparisons=[("SQL", "KQL reads top-down with pipes: Perf | where … | summarize … instead of SELECT … FROM … GROUP BY."), ("CloudWatch Logs Insights", "AWS's query language for logs.")],
    misconceptions=[("KQL can modify data.", "It's read-only for queries."), ("summarize keeps all columns.", "Only the aggregates and by-columns remain.")],
    decisions=["Save common queries and share them in query packs.", "Filter by time and table early for performance and cost."],
    docs=[("Log queries in Azure Monitor", KQL), ("KQL tutorial", ML + "azure-monitor/logs/get-started-queries"), ("KQL quick reference", "https://learn.microsoft.com/kusto/query/kql-quick-reference")],
)
qa("AZ104-5.1.3", 2, "command", "Which query lists computers that have not sent a heartbeat in the last 5 minutes?", [("Heartbeat | summarize LastSeen = max(TimeGenerated) by Computer | where LastSeen < ago(5m)", "Correct."), ("Heartbeat | where TimeGenerated > ago(5m)", "Returns those that did."), ("Perf | take 5", "No."), ("AzureActivity | where Computer == '*'", "No.")], "a", "Summarize the latest heartbeat per computer, then filter.", KQL)
qa("AZ104-5.1.3", 2, "command", "Which operator groups rows and calculates aggregates such as avg() and count()?", [("summarize", "Correct."), ("project", "Selects columns."), ("extend", "Adds columns."), ("where", "Filters.")], "a", "summarize … by …", KQL)
qa("AZ104-5.1.3", 2, "scenario", "You want an hourly CPU trend chart per computer. Which part is essential?", [("summarize avg(CounterValue) by bin(TimeGenerated, 1h), Computer | render timechart", "Correct."), ("take 100", "Random sample."), ("project Computer", "Drops values."), ("order by Computer", "Sorting only.")], "a", "bin() groups by time.", KQL)

# ================================================================ 5.1.4 Alerts
lesson(
    id="az104-alerts", exam=E, title="Alert rules, action groups and alert processing rules", objectives=["AZ104-5.1.4"], minutes=40,
    objective="Create metric, log search and activity log alert rules, configure action groups, and use alert processing rules to route or suppress notifications.",
    prereqs=[("Querying logs with KQL", "AZ104-5.1.3", "az104-kql")],
    foundation=["An alert rule watches a signal (a metric, a log query or an activity log event) and fires when its condition is met.", "An action group says who to notify and what to run. An alert processing rule changes what happens to fired alerts, for example silencing them during maintenance."],
    engineer=["Alert rule = scope + condition (signal, aggregation, operator, threshold or dynamic threshold, lookback window and evaluation frequency) + actions + details (severity 0–4, name, auto-resolve).",
              "Types: metric alerts (near real time, stateful: they resolve automatically), log search alerts (KQL on a schedule), activity log alerts (for example a VM deleted, or Service Health and Resource Health events), smart detection, Prometheus alerts.",
              "Action groups: notifications (email, SMS, Azure app push, voice, email Azure Resource Manager role) and actions (Automation runbook, Azure Functions, Event Hubs, ITSM, Logic Apps, webhook/secure webhook). Reusable across many rules. Rate limits apply to SMS/voice/email.",
              "Alert processing rules: scope (subscription, resource group, resource) with filters (severity, alert rule, resource type…), action = add action groups or suppress notifications, optional schedule (once or recurring). Suppressed alerts still fire and appear in the alerts list.",
              "Alert state: monitor condition Fired/Resolved, and user response New/Acknowledged/Closed."],
    anim=("monitor-sim", "Alert rules, action groups and processing rules tab."),
    diagram=([("sig", "Signal: CPU metric / KQL / activity log", 20, 120, "compute"), ("rule", "Alert rule (threshold, window)", 240, 120, "security"), ("apr", "Alert processing rule", 450, 40, "service"), ("ag", "Action group: email, SMS, Logic App", 450, 200, "user"), ("ops", "On-call", 680, 120, "user")],
             [("sig", "rule"), ("rule", "apr", "fired"), ("apr", "ag"), ("ag", "ops")]),
    example=("Paging the right team", ["A metric alert fires when average CPU > 80% over 5 minutes on any production VM. One action group emails and texts the ops team and calls a Logic App to open a ticket.",
                                       "An alert processing rule suppresses notifications every Sunday 01:00–03:00 when patching runs."]),
    config=cfg(["Monitor > Alerts > Create > Alert rule: scope, condition, actions, details.", "Monitor > Alerts > Action groups > Create: notifications and actions.", "Monitor > Alerts > Alert processing rules > Create: scope, filters, suppress or apply action group, schedule."],
               "az monitor action-group create -g rg-mon -n ag-ops --short-name ops --action email oncall oncall@contoso.com --action sms oncall 1 5555550100\naz monitor metrics alert create -g rg-mon -n cpu-high --scopes $VM_ID --condition \"avg Percentage CPU > 80\" --window-size 5m --evaluation-frequency 1m --severity 2 --action ag-ops\naz monitor alert-processing-rule create -g rg-mon -n suppress-patching --scopes /subscriptions/<id>/resourceGroups/rg-prod --rule-type RemoveAllActionGroups --schedule-recurrence-type Weekly --schedule-recurrence Sunday --schedule-recurrence-start-time 01:00:00 --schedule-recurrence-end-time 03:00:00",
               "$email = New-AzActionGroupEmailReceiverObject -Name oncall -EmailAddress oncall@contoso.com\nNew-AzActionGroup -ResourceGroupName rg-mon -Name ag-ops -ShortName ops -Location global -EmailReceiver $email\n$c = New-AzMetricAlertRuleV2Criteria -MetricName 'Percentage CPU' -TimeAggregation Average -Operator GreaterThan -Threshold 80\nAdd-AzMetricAlertRuleV2 -Name cpu-high -ResourceGroupName rg-mon -TargetResourceId $vmId -Condition $c -WindowSize 00:05:00 -Frequency 00:01:00 -Severity 2 -ActionGroupId (Get-AzActionGroup -ResourceGroupName rg-mon -Name ag-ops).Id"),
    lab=lab("Tune an alert so it fires on the spike, notifies the team and stays quiet during maintenance.", ["Run the default (Average over 1 hour) and see the alert missed.", "Apply 'Average over 5 minutes'.", "Apply 'Maintenance window suppression'.", "Apply 'No action group'."],
            ["Window and aggregation decide firing", "Processing rules suppress notifications only"], [("alert-notified", "Alert fired and notified the team"), ("alert-suppressed", "Suppressed notifications during maintenance"), ("alert-missed", "Saw an alert miss the spike"), ("alert-no-action", "Saw an alert with no action group")],
            ["Lookback window too long", "No action group", "Expecting suppression to stop the alert itself"]),
    troubleshooting=[("Alert never fires.", "Window/aggregation smooths the signal, or wrong scope.", "Shorter window, Maximum aggregation, check the scope."), ("Alert fires but nobody is notified.", "No action group, or an alert processing rule suppresses it.", "Attach an action group; review processing rules."), ("Too many SMS alerts.", "Rate limiting or noisy thresholds.", "Use dynamic thresholds and severity-based routing.")],
    comparisons=[("Amazon CloudWatch alarms + SNS", "Alarm ≈ alert rule; SNS topic ≈ action group."), ("Service Health alerts", "Activity log alerts for Azure platform incidents affecting your subscriptions.")],
    misconceptions=[("Alert processing rules delete alerts.", "They add action groups or suppress notifications; alerts still fire."), ("Each alert rule needs its own action group.", "Action groups are reusable.")],
    decisions=["Use severity levels consistently and route by severity with processing rules.", "Prefer dynamic thresholds for noisy metrics.", "Manage alert rules as code (Bicep/ARM) per environment."],
    docs=[("Azure Monitor alerts overview", ALERTS), ("Action groups", AG), ("Alert processing rules", APR), ("Create a metric alert", ML + "azure-monitor/alerts/alerts-create-metric-alert-rule")],
)
qa("AZ104-5.1.4", 2, "scenario", "During weekly patching, alerts should still be recorded but nobody should be paged. What do you configure?", [("An alert processing rule that suppresses notifications on a weekly schedule", "Correct."), ("Disable every alert rule weekly", "Manual and loses alerts."), ("Delete the action group", "Breaks all notifications."), ("Raise thresholds", "Hides real problems.")], "a", "Processing rules suppress notifications without stopping alerts.", APR)
qa("AZ104-5.1.4", 2, "configuration", "You want one place to define 'email ops, SMS on-call and run a Logic App' for 30 alert rules. What do you create?", [("An action group", "Correct."), ("A data collection rule", "Collection."), ("A diagnostic setting", "Collection."), ("A workbook", "Visualisation.")], "a", "Action groups are reusable.", AG)
qa("AZ104-5.1.4", 2, "scenario", "You need an alert whenever someone deletes a VM in a subscription. Which alert type?", [("Activity log alert on the Delete Virtual Machine operation", "Correct."), ("Metric alert on CPU", "No."), ("Smart detection", "Application Insights."), ("Connection Monitor", "Network.")], "a", "Control-plane operations are in the activity log.", ALERTS)
qa("AZ104-5.1.4", 3, "troubleshooting", "A metric alert on Average CPU > 90% over 1 hour never fired, although CPU hit 97% for 4 minutes. Why?", [("The 1-hour average never exceeded 90%", "Correct."), ("Metric alerts don't support CPU", "They do."), ("The action group was missing", "Then it would fire without notifying."), ("Metric alerts need Log Analytics", "No.")], "a", "Use a shorter window or Maximum.", ALERTS)

# ================================================================ 5.1.5 + 5.1.6 Insights and Network Watcher
lesson(
    id="az104-insights-network-watcher", exam=E, title="Azure Monitor Insights, Network Watcher and Connection Monitor", objectives=["AZ104-5.1.5", "AZ104-5.1.6"], minutes=45,
    objective="Configure and interpret VM insights, Storage insights and Network insights, and use Network Watcher and Connection Monitor to monitor connectivity.",
    prereqs=[("Metrics and log settings", "AZ104-5.1.2", "az104-monitor-metrics-logs"), ("Troubleshooting network connectivity", "AZ104-4.1.5", "az104-network-troubleshooting")],
    foundation=["Insights are ready-made monitoring experiences for a type of resource: VMs, storage accounts, networks, containers and more.", "Network Watcher diagnoses and monitors network connectivity; Connection Monitor tests connections continuously."],
    engineer=["VM insights: enable on VMs/scale sets (installs Azure Monitor Agent and a DCR sending performance data to a workspace; the optional Map feature adds dependency data). Shows CPU, memory, disk and network trends, top N machines and processes/connections.",
              "Storage insights: built from storage platform metrics, no setup: capacity, availability, transactions, end-to-end and server latency, failures by type across accounts.",
              "Network insights: topology and health of network resources (gateways, load balancers, VNets), with links to resource-specific insights and Connection Monitor results.",
              "Network Watcher tools: topology, IP flow verify, NSG diagnostics, next hop, effective security rules, connection troubleshoot, packet capture, VPN troubleshoot, VNet flow logs and Traffic analytics.",
              "Connection Monitor: test groups of sources (Azure VMs with the Network Watcher agent extension, Arc-enabled or on-premises machines with Azure Monitor Agent) and destinations (IP, FQDN, Azure resources) using TCP, HTTP or ICMP test configurations with thresholds for checks failed % and round-trip time. Results go to Log Analytics and can trigger alerts."],
    anim=("monitor-sim", "Insights and Network Watcher, and Connection Monitor tabs."),
    diagram=([("vm", "VMs (AMA + DCR)", 20, 40, "compute"), ("st", "Storage accounts", 20, 140, "storage"), ("net", "Network resources", 20, 240, "network"), ("ins", "Azure Monitor Insights", 300, 140, "service"), ("cm", "Connection Monitor", 560, 60, "security"), ("law", "Log Analytics", 560, 220, "storage")],
             [("vm", "ins"), ("st", "ins"), ("net", "ins"), ("cm", "law"), ("vm", "cm", "agent tests")]),
    example=("Watching the on-premises link", ["Connection Monitor tests TCP 443 from three Azure VMs to an on-premises ERP server every 30 seconds with thresholds of 5% failed checks and 100 ms RTT. When the VPN degrades, the test state turns Fail and the ops action group is alerted; the topology view shows the failing hop."]),
    config=cfg(["Monitor > Virtual Machines (VM insights) > Configure insights: choose a DCR and workspace.", "Monitor > Storage accounts (Storage insights): review failures and latency.", "Network Watcher > Connection monitor > Create: sources, destinations, test configuration, thresholds, alerting.", "Monitor > Networks: topology and health."],
               "az vm extension set -g rg-app --vm-name vm-app -n NetworkWatcherAgentLinux --publisher Microsoft.Azure.NetworkWatcher\naz network watcher connection-monitor create -n cm-erp --location eastus --endpoint-source-name vm-app --endpoint-source-resource-id $VM_ID --endpoint-dest-name erp --endpoint-dest-address erp.contoso.local --test-config-name tcp443 --protocol Tcp --tcp-port 443 --frequency 30 --threshold-failed-percent 5 --threshold-round-trip-time 100",
               "Set-AzVMExtension -ResourceGroupName rg-app -VMName vm-app -Name NetworkWatcherAgentWindows -Publisher Microsoft.Azure.NetworkWatcher -Type NetworkWatcherAgentWindows -TypeHandlerVersion 1.4\nGet-AzNetworkWatcherConnectionMonitor -Location eastus"),
    lab=lab("Pick the right Insight or Network Watcher tool and set up Connection Monitor.", ["Insights and Network Watcher: answer every requirement.", "Connection Monitor: run the default (no agent).", "Apply 'Install the agent', then 'Latency degradation' and 'Destination down'."],
            ["VM insights needs AMA + DCR", "Connection Monitor needs an agent on sources", "Thresholds decide Pass/Fail"], [("insights-correct", "Chose the right monitoring feature"), ("cm-pass", "Saw a passing connection test"), ("cm-alert", "Saw a threshold breach raise an alert"), ("cm-no-agent", "Diagnosed a missing agent")],
            ["No agent on the source VM", "Thresholds too loose"]),
    troubleshooting=[("VM insights shows no data.", "No DCR association or agent not reporting.", "Check the agent extension and Heartbeat table."), ("Connection Monitor source shows unavailable.", "Network Watcher agent missing or Network Watcher not enabled in the region.", "Install the extension; enable Network Watcher."), ("Storage insights shows high server latency.", "Service-side processing (hot partitions, large operations).", "Investigate request patterns; E2E vs server latency difference indicates client/network.")],
    comparisons=[("CloudWatch Container/Lambda Insights and VPC Reachability Analyzer", "AWS equivalents."), ("Network Watcher one-off tools", "Connection Monitor is continuous; IP flow verify/next hop are point-in-time.")],
    misconceptions=[("Storage insights needs an agent.", "It uses platform metrics."), ("Connection Monitor works without anything on the VM.", "Azure VM sources need the Network Watcher agent extension.")],
    decisions=["Enable VM insights through Azure Policy for all production VMs.", "Monitor critical hybrid paths with Connection Monitor and alert on thresholds."],
    docs=[("VM insights overview", VMI), ("Storage insights", ML + "storage/common/storage-insights-overview"), ("Network insights", ML + "network-watcher/network-insights-overview"), ("Connection Monitor overview", CM), ("Network Watcher overview", NW)],
)
